CREATE OR REPLACE FUNCTION sessions.selected_session_turn_ids(
  p_org text, p_workspace text, p_event_workspace text, p_source text, p_session text
) RETURNS uuid[] LANGUAGE sql STABLE
SET search_path = pg_catalog, sessions, pg_temp AS $selected_turns$
  SELECT COALESCE(array_agg(t.id ORDER BY t.id), ARRAY[]::uuid[]) FROM (
    SELECT t.id, COALESCE(
      NULLIF(t.metadata->>'nativeCli', ''),
      NULLIF(t.metadata->>'source', ''),
      CASE WHEN t.source <> '' AND t.source <> t.session_owner THEN t.source END,
      CASE WHEN EXISTS (
        SELECT 1 FROM sessions.convergence_events owner_event
         WHERE owner_event.org_id = t.org_id AND COALESCE(owner_event.workspace_id, '') = p_event_workspace
           AND owner_event.session_id = t.session_id AND owner_event.source = t.session_owner
      ) THEN t.session_owner END
    ) AS attributed
    FROM sessions.conversation_turns t
    WHERE t.org_id = p_org AND t.workspace_id = p_workspace AND t.session_id = p_session
  ) t
  WHERE t.attributed = p_source
     OR (t.attributed IS NULL AND NOT EXISTS (
       SELECT 1 FROM sessions.convergence_events other
        WHERE other.org_id = p_org AND COALESCE(other.workspace_id, '') = p_event_workspace
          AND other.session_id = p_session AND other.source <> p_source));
$selected_turns$;
